import { mapArrayElementsKeysToObjectKeys } from '../../../../helpers/utility'
import { TEAM_ACTION } from './actions'

const reducers = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case TEAM_ACTION.ROLES_LIST:
    case TEAM_ACTION.PERMISSION_LIST:
    case TEAM_ACTION.ADD_ROLE_PERMISSIONS:
    case TEAM_ACTION.REVOKE_PERMISSION:
    case TEAM_ACTION.ADD_GROUP:
    case TEAM_ACTION.USER_LIST:
    case TEAM_ACTION.ADD_USER:
    case TEAM_ACTION.PROVIDER_LIST:
    case TEAM_ACTION.AGENT_PROVIDER_LIST:
    case TEAM_ACTION.UPDATE_USER_STATUS:
    case TEAM_ACTION.DELETE_USER:
    case TEAM_ACTION.UPDATE_USER:
    case TEAM_ACTION.GROUP_PERMISSIONS:
    case TEAM_ACTION.ADD_PERMISSION:
    case TEAM_ACTION.GROUP_USERS:
    case TEAM_ACTION.ADD_USER_TO_GROUP:
    case TEAM_ACTION.REMOVE_USER_FROM_GROUP:
      return { ...state, ...payload }
    case TEAM_ACTION.RESET_STATE:
      return { ...state, ...mapArrayElementsKeysToObjectKeys(payload) }
    default:
      return state
  }
}

export default reducers
