import React from 'react'
import { Modal, Descriptions } from 'antd'
import { map } from 'lodash'

const { Item } = Descriptions

const UserDetailModal = ({ visible, userData, closeModal }) => {
  return (
    <Modal
      visible={visible}
      title='User Detail'
      onOk={closeModal}
      onCancel={closeModal}
      cancelButtonProps={{ style: { display: 'none' } }}
      okText='Close'
      width={700}
    >
      <Descriptions column={3} layout='vertical' bordered>
        <Item label={<b>Name</b>}>{userData.name}</Item>
        <Item label={<b>Email</b>}>{userData.email}</Item>
        <Item label={<b>Phone</b>}>{userData.phone}</Item>
        <Item label={<b>Provider</b>}>{userData.provider || '-'}</Item>
        <Item label={<b>Agent Provider</b>} span={2}>{userData.agent_provider || '-'}</Item>
        <Item label={<b>Groups</b>}>{Array.isArray(userData.groups) ? map(userData.groups, 'name').map(groupName => <div key={groupName}>{groupName}</div>) : ''}</Item>
      </Descriptions>
    </Modal>
  )
}
export default UserDetailModal
