import React from 'react'
import { connect } from 'react-redux'
import { Button, Icon, Dropdown, Menu } from 'antd'

const UserActionsMenu = ({ permissions, rowData, viewUserDetail, editUser, updateUserStatusRequest, deleteUser }) => {
  const can = permission => permissions.includes(permission)
  const canManage = can('ops.can_perform_team_actions')
  const canDelete = can('ops.can_delete_user') && !rowData.is_active

  const items = [
    <Menu.Item key='detail' onClick={() => viewUserDetail(rowData)}>
      <Icon type='eye' /> Detail
    </Menu.Item>
  ]

  if (canManage) {
    items.push(
      <Menu.Item key='edit' onClick={() => editUser(rowData)}>
        <Icon type='edit' /> Edit
      </Menu.Item>,
      <Menu.Item
        key='status'
        onClick={() => updateUserStatusRequest({ user_id: rowData.id, activate: !rowData.is_active })}
      >
        {
          rowData.is_active
            ? <span><Icon type='stop' /> Deactivate</span>
            : <span><Icon type='check' /> Activate</span>
        }
      </Menu.Item>
    )
  }

  if (canDelete) {
    items.push(
      <Menu.Divider key='delete-divider' />,
      <Menu.Item key='delete' onClick={() => deleteUser(rowData)}>
        <span style={{ color: '#f5222d' }}><Icon type='delete' /> Delete</span>
      </Menu.Item>
    )
  }

  return (
    <Dropdown trigger={['click']} overlay={<Menu>{items}</Menu>}>
      <Button>
        Actions <Icon type='down' />
      </Button>
    </Dropdown>
  )
}

export default connect(
  state => ({
    permissions: state.Auth.permissions || []
  }),
  {}
)(UserActionsMenu)
