/* eslint-disable react-hooks/exhaustive-deps */
import { useEffect, useMemo } from 'react'
import { Modal, Form, Select, Alert, message, Spin, Input } from 'antd'
import { useGlobalApisContext, useRoles, useUserContext } from '../../../state/hooks/useTeamContext'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { addUserFormItemConfigs } from './utility'
import { pickBy } from 'lodash'
import { emailRegExp } from '../../../../../../constants/validation-regex';

const { Option } = Select

const AddUserModal = ({ visible, form, toggleAddModal, closeModal, data, ...props }) => {
  const { getFieldDecorator } = form
  const { addUserRequest, addUserData, getUserList, updateUserRequest, resetState } = useUserContext()
  const { getRolesList, roleListData } = useRoles()
  const [{
    ADD_USER_ERROR,
    addUserStatus,
    addUserErrorData,
    ROLE_LIST_ERROR,
    roleListStatus,
    PROVIDER_LIST_ERROR,
    providerListStatus,
    AGENT_PROVIDER_LIST_ERROR,
    agentProviderListStatus,
    UPDATE_USER_ERROR,
    updateUserStatus,
    updateUserErrorData
  }] = useErrorContextValue()
  const { getProviderList, providerListData } = useGlobalApisContext()
  const [{ ADD_USER_LOADER, ROLE_LIST_LOADER, PROVIDER_LIST_LOADER, AGENT_PROVIDER_LIST_LOADER, UPDATE_USER_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()

  const handleOk = () => {
    form.validateFields((err, values) => {
      if (!err) {
        const valuesToBeSent = pickBy(values)
        if (data) {
          valuesToBeSent.id = data.id
          updateUserRequest(valuesToBeSent)
        } else {
          addUserRequest(valuesToBeSent)
        }
      }
    })
  }

  useEffect(() => {
    if (addUserStatus === 'success' || updateUserStatus === 'success') {
      if (addUserStatus === 'success') {
        message.success(
          addUserData?.reactivated
            ? 'Previously deleted user has been restored.'
            : 'User added successfully.'
        )
      }
      if (updateUserStatus === 'success') {
        message.success('User updated successfully.')
      }
      form.resetFields()
      toggleAddModal(false)
      getUserList()
      resetState(['addUserData', 'updateUserData'])
      resetError(['addUserStatus', ' updateUserStatus'])
    }
  }, [addUserStatus, updateUserStatus])

  useEffect(() => {
    if (data) {
      form.setFields({
        name: {
          value: data.name
        },
        email: {
          value: data.email
        },
        phone: {
          value: data.phone
        },
        groups: {
          value: Array.isArray(data.groups) ? data.groups.map(({ name }) => name) : []
        },
        provider: {
          value: data.provider
        },
        agent_provider: {
          value: data.agent_provider
        }
      })
    }
  }, [data])

  useEffect(() => {
    if (ADD_USER_ERROR && addUserErrorData && addUserErrorData.error) {
      const error = addUserErrorData.error
      for (const key in error) {
        const values = form.getFieldsValue()
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [ADD_USER_ERROR, addUserErrorData])

  useEffect(() => {
    if (UPDATE_USER_ERROR && updateUserErrorData && updateUserErrorData.error) {
      const error = updateUserErrorData.error
      for (const key in error) {
        const values = form.getFieldsValue()
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [UPDATE_USER_ERROR, updateUserErrorData])

  useEffect(() => {
    getRolesList()
    getProviderList()
    return () => {
      resetState([
        'addUserRequest',
        'addUserData',
        'addUserErrorData',
        'getUserList',
        'updateUserRequest',
        'updateUserData'
      ])
      resetError([
        'ADD_USER_ERROR',
        'addUserStatus',
        'ROLE_LIST_ERROR',
        'roleListStatus',
        'PROVIDER_LIST_ERROR',
        'providerListStatus',
        'AGENT_PROVIDER_LIST_ERROR',
        'agentProviderListStatus',
        'UPDATE_USER_ERROR',
        'updateUserStatus'
      ])
    }
  }, [])

  const emailRules = useMemo(() => {
    if (data?.agent_provider) {
      // we are doing only for agent_provider support as of now
      const emailRules = {
        ...JSON.parse(JSON.stringify(addUserFormItemConfigs.email))
      }
      emailRules.rules[1] = {
        ...emailRules.rules[1],
        pattern: emailRegExp
      }
      return emailRules
    }
    return addUserFormItemConfigs.email
  }, [data?.agent_provider])

  return (
    <Modal
      visible={visible}
      title={data ? 'Edit User' : 'Add New User'}
      okText={data ? 'Update' : 'Add'}
      onCancel={closeModal}
      onOk={handleOk}
    >

      {(ADD_USER_ERROR) && !addUserErrorData && <Alert type='error' message={addUserStatus} banner />}
      {(ROLE_LIST_ERROR) && <Alert type='error' message={roleListStatus} banner />}
      {(PROVIDER_LIST_ERROR) && <Alert type='error' message={providerListStatus} banner />}
      {(AGENT_PROVIDER_LIST_ERROR) && <Alert type='error' message={agentProviderListStatus} banner />}
      {(UPDATE_USER_ERROR && !updateUserErrorData) && <Alert type='error' message={updateUserStatus} banner />}
      <Spin spinning={!!ADD_USER_LOADER || !!ROLE_LIST_LOADER || !!AGENT_PROVIDER_LIST_LOADER || !!PROVIDER_LIST_LOADER || !!UPDATE_USER_LOADER}>
        <Form>
          <Form.Item
            label='Name'
            hasFeedback
          >
            {getFieldDecorator('name', addUserFormItemConfigs.name)(
              <Input />
            )}
          </Form.Item>
          <Form.Item
            label='Email'
            hasFeedback
          >
            {
              getFieldDecorator('email', emailRules)(
                <Input disabled={!!data} />
              )
            }
          </Form.Item>
          <Form.Item
            label='Phone'
            hasFeedback
          >
            {getFieldDecorator('phone', addUserFormItemConfigs.phone)(
              <Input />
            )}
          </Form.Item>
          <Form.Item
            label='Groups'
            hasFeedback
          >
            {
              getFieldDecorator(
                'groups',
                addUserFormItemConfigs.groups
              )(
                <Select
                  mode='multiple'
                >
                  {
                    !ROLE_LIST_ERROR && Array.isArray(roleListData)
                      ? (
                          roleListData.map(role => (
                            <Option key={role.name} value={role.name}>{role.name}</Option>
                          ))
                        )
                      : null
                  }
                </Select>
              )
            }
          </Form.Item>
          <Form.Item
            label='Provider'
            hasFeedback
          >
            {
              getFieldDecorator(
                'provider',
                addUserFormItemConfigs.provider
              )(
                <Select allowClear>
                  {
                    !PROVIDER_LIST_ERROR && Array.isArray(providerListData)
                      ? (
                          providerListData.map(provider => (
                            <Option key={provider.id} value={provider.code}>{provider.name}</Option>
                          ))
                        )
                      : null
                  }
                </Select>
              )
            }
          </Form.Item>
          <Form.Item
            label='Agent Provider'
            hasFeedback
          >
            {getFieldDecorator('agent_provider', addUserFormItemConfigs.agent_provider)(
              <Input />
            )}
          </Form.Item>
        </Form>

      </Spin>
    </Modal>
  )
}
export default Form.create({ name: 'add-edit-user' })(AddUserModal)
