/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import { useHistory } from 'react-router'
import { Button, Table, Col, Icon, Alert, Spin, Empty, Input, message } from 'antd'
import { userColumns } from './utility'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { RowWithMargin } from '../../../../EmployeeBenefits/CommonComponents'
import { ColTextAlignRight } from '../../../../EmployeeBenefits/CommonComponents/index.style'
import { useUserContext } from '../../../state/hooks/useTeamContext'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import AddEditUserModal from './addUser'
import UserDetailModal from './userDetailModal'
import DeleteUserModal from './deleteUserModal'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'

const { Search } = Input

const Users = () => {
  const history = useHistory()
  const { getUserList, userListData, updateUserStatusRequest, deleteUserRequest, resetState } = useUserContext()
  const [{ USER_LIST_ERROR, userListStatus, UPDATE_USER_STATUS_ERROR, updateUserStatusStatus, DELETE_USER_ERROR, deleteUserStatus }] = useErrorContextValue()
  const [{ USER_LIST_LOADER, UPDATE_USER_STATUS_LOADER, DELETE_USER_LOADER }] = useLoaderContextValue()
  const [addModal, toggleAddModal] = useState({ visible: false, data: null })
  const [detailModal, toggleDetailModal] = useState(null)
  const [deleteModal, toggleDeleteModal] = useState(null)
  const [lastStatusAction, setLastStatusAction] = useState(null)
  const [searchText, setSearchText] = useState(null)
  const { resetError } = useResetError()

  const getFilteredData = () => {
    if (searchText) {
      return userListData.filter(user => new RegExp(searchText, 'i').test(user.name) || new RegExp(searchText, 'i').test(user.email))
    }
    return userListData
  }

  const closeAddModal = () => toggleAddModal({ visible: false, data: null })
  const closeDetailModal = () => toggleDetailModal(null)
  const closeDeleteModal = () => toggleDeleteModal(null)
  const editUser = data => toggleAddModal({ visible: true, data })
  const viewUserDetail = data => toggleDetailModal(data)
  const deleteUser = data => toggleDeleteModal(data)

  const changeUserStatus = payload => {
    setLastStatusAction(payload.activate ? 'activate' : 'deactivate')
    updateUserStatusRequest(payload)
  }

  useEffect(() => {
    if (updateUserStatusStatus === 'success') {
      message.success(lastStatusAction === 'activate' ? 'User activated successfully.' : 'User deactivated successfully.')
      setLastStatusAction(null)
      getUserList()
      resetError(['updateUserStatusStatus'])
    }
  }, [updateUserStatusStatus])

  useEffect(() => {
    if (deleteUserStatus === 'success') {
      message.success('User deleted successfully.')
      closeDeleteModal()
      getUserList()
      resetError(['deleteUserStatus'])
    }
  }, [deleteUserStatus])

  useEffect(() => {
    getUserList()
    return () => {
      resetError([
        'USER_LIST_ERROR',
        'userListStatus',
        'UPDATE_USER_STATUS_ERROR',
        'updateUserStatusStatus',
        'DELETE_USER_ERROR',
        'deleteUserStatus'
      ])
      resetState([
        'getUserList',
        'userListData',
        'updateUserStatusRequest',
        'updateUserStatusData',
        'deleteUserData'
      ])
    }
  }, [])

  return (
    <EbEmptyPage
      history={history}
    >
      <Spin spinning={!!USER_LIST_LOADER || !!UPDATE_USER_STATUS_LOADER || !!DELETE_USER_LOADER}>
        {(USER_LIST_ERROR) && <Alert type='error' message={userListStatus} banner />}
        {(UPDATE_USER_STATUS_ERROR) && <Alert type='error' message={updateUserStatusStatus} banner />}
        {(DELETE_USER_ERROR) && <Alert type='error' message={deleteUserStatus} banner />}
        <RowWithMargin type='flex' justify='space-between'>
          <Col span={14}>
            <h2>Operations Panel User List</h2>
          </Col>
          <Col span={6}>
            <Search
              placeholder='Search..'
              onChange={(e) => setSearchText(e.target.value)}
              disabled={!userListData}
              allowClear
            />
          </Col>
          <PermissionCheckerV2 requiredPermission='ops.can_perform_team_actions'>
            <ColTextAlignRight
              span={4}
            >
              <Button
                type='primary'
                onClick={() => toggleAddModal({ visible: true, data: null })}
              >
                <Icon type='user-add' />
                Add User
              </Button>
            </ColTextAlignRight>
          </PermissionCheckerV2>
        </RowWithMargin>
        {
          Array.isArray(userListData)
            ? (
              <Table
                columns={userColumns({ updateUserStatusRequest: changeUserStatus, editUser, viewUserDetail, deleteUser })}
                dataSource={getFilteredData()}
              />
              )
            : <Empty />
        }
      </Spin>
      {
        addModal.visible && (
          <AddEditUserModal
            visible={addModal.visible}
            toggleAddModal={toggleAddModal}
            closeModal={closeAddModal}
            data={addModal.data}
          />
        )
      }
      {
        detailModal && (
          <UserDetailModal
            visible={!!detailModal}
            closeModal={closeDetailModal}
            userData={detailModal}
          />
        )
      }
      {
        deleteModal && (
          <DeleteUserModal
            visible={!!deleteModal}
            closeModal={closeDeleteModal}
            userData={deleteModal}
            onConfirm={deleteUserRequest}
            confirmLoading={!!DELETE_USER_LOADER}
          />
        )
      }
    </EbEmptyPage>
  )
}

export default Users
