import { Tag } from 'antd'
import { emailPpDomainRegExp, phoneRegExp } from '../../../../../../constants/validation-regex'
import UserActionsMenu from './userActions'

export const userColumns = ({ updateUserStatusRequest, editUser, viewUserDetail, deleteUser }) => ([
  {
    title: 'Name',
    dataIndex: 'name',
    width: '30%',
    render: name => <span style={{ wordBreak: 'break-word' }}>{name}</span>
  },
  {
    title: 'Email',
    dataIndex: 'email',
    render: email => <span style={{ wordBreak: 'break-word' }}>{email}</span>
  },
  {
    title: 'Active',
    dataIndex: 'is_active',
    width: 100,
    align: 'center',
    render: (isActive) => isActive ? <Tag color='#87d068'>True</Tag> : <Tag color='#f50'>False</Tag>
  },
  {
    title: 'Actions',
    width: 140,
    align: 'center',
    render: (rowData) => (
      <UserActionsMenu
        rowData={rowData}
        viewUserDetail={viewUserDetail}
        editUser={editUser}
        updateUserStatusRequest={updateUserStatusRequest}
        deleteUser={deleteUser}
      />
    )
  }

])

