import React from 'react'
import { Modal, Form, Input, Alert } from 'antd'

const { TextArea } = Input
const { Item } = Form

const DeleteUserModal = ({ visible, userData, closeModal, onConfirm, form, confirmLoading }) => {
  const { getFieldDecorator, validateFields } = form

  const handleOk = () => {
    validateFields((errors, values) => {
      if (errors) return
      onConfirm({ user_id: userData.id, remark: values.remark.trim() })
    })
  }

  return (
    <Modal
      visible={visible}
      title='Delete User'
      onOk={handleOk}
      onCancel={closeModal}
      okText='Delete'
      okButtonProps={{ type: 'danger' }}
      confirmLoading={confirmLoading}
      destroyOnClose
    >
      <Alert
        type='warning'
        showIcon
        message={`${userData.name} (${userData.email}) will be hidden from the Control Panel.`}
        style={{ marginBottom: 16 }}
      />
      <Form layout='vertical'>
        <Item label='Remark'>
          {getFieldDecorator('remark', {
            rules: [
              { required: true, message: 'Remark is required' },
              { whitespace: true, message: 'Remark is required' },
              { max: 500, message: 'Remark should not exceed 500 character' }
            ]
          })(
            <TextArea rows={4} placeholder='Reason for deleting this user' />
          )}
        </Item>
      </Form>
    </Modal>
  )
}

export default Form.create({ name: 'delete_user' })(DeleteUserModal)
